from itertools import product

# Q8 elements as tuples (sign, unit) where unit in {1,i,j,k}
# Represent as: 1=(+,1), -1=(-,1), i=(+,i), -i=(-,i), etc.
# Use a simpler representation: elements 0..7
# 0=1, 1=-1, 2=i, 3=-i, 4=j, 5=-j, 6=k, 7=-k

elements = ['1', '-1', 'i', '-i', 'j', '-j', 'k', '-k']

# Multiplication table from the problem
table = {
    (0,0):0, (0,1):1, (0,2):2, (0,3):3, (0,4):4, (0,5):5, (0,6):6, (0,7):7,
    (1,0):1, (1,1):0, (1,2):3, (1,3):2, (1,4):5, (1,5):4, (1,6):7, (1,7):6,
    (2,0):2, (2,1):3, (2,2):1, (2,3):0, (2,4):6, (2,5):7, (2,6):5, (2,7):4,
    (3,0):3, (3,1):2, (3,2):0, (3,3):1, (3,4):7, (3,5):6, (3,6):4, (3,7):5,
    (4,0):4, (4,1):5, (4,2):7, (4,3):6, (4,4):1, (4,5):0, (4,6):2, (4,7):3,
    (5,0):5, (5,1):4, (5,2):6, (5,3):7, (5,4):0, (5,5):1, (5,6):3, (5,7):2,
    (6,0):6, (6,1):7, (6,2):4, (6,3):5, (6,4):3, (6,5):2, (6,6):1, (6,7):0,
    (7,0):7, (7,1):6, (7,2):5, (7,3):4, (7,4):2, (7,5):3, (7,6):0, (7,7):1,
}

def mul(a, b):
    return table[(a, b)]

def inv(a):
    for b in range(8):
        if mul(a, b) == 0:
            return b
    return None

# Find all subgroups by checking all subsets containing 0 (identity)
from itertools import combinations

subgroups = []
for size in range(1, 8):
    for subset in combinations(range(1, 8), size):
        H = {0} | set(subset)
        # Check closure
        closed = True
        for a in H:
            for b in H:
                if mul(a, b) not in H:
                    closed = False
                    break
            if not closed:
                break
        if closed:
            # Check inverses (closure + finite + identity => subgroup, but let's verify)
            has_inv = all(inv(a) in H for a in H)
            if has_inv:
                subgroups.append(H)

# Add Q8 itself
subgroups.append(set(range(8)))

# Check normality: gHg^{-1} = H for all g
normal_subgroups = []
for H in subgroups:
    is_normal = True
    for g in range(8):
        conjugate = {mul(mul(g, h), inv(g)) for h in H}
        if conjugate != H:
            is_normal = False
            break
    if is_normal:
        normal_subgroups.append(H)

print(f"Total subgroups found: {len(subgroups)}")
print(f"Normal subgroups: {len(normal_subgroups)}")
print()
for H in sorted(normal_subgroups, key=lambda s: (len(s), sorted(s))):
    names = sorted([elements[h] for h in H], key=lambda x: elements.index(x))
    print(f"  {{{', '.join(names)}}}  (order {len(H)})")

print()
print("All subgroups are normal:", len(subgroups) == len(normal_subgroups))
EOF

